 async function save(automatic=false,onFailure?:(message:string)=>void):Promise<boolean>{
  const s=live.current;
  if(!s.file||!s.project||!s.file.editable||saveLock.current||s.saving||chapterRead.current||composing.current)return false;
  if(s.text===normalized(s.file)&&!s.saveNeedsVerification)return true;
  if(s.file.line_ending==='MIXED'){const message=translateUI("navigation:mixedLineEndingsUseExternalEditor");setError(message);onFailure?.(message);return false;}
  const generation=loadId.current,path=s.file.path,url='/api/projects/'+s.project+'/files/content';
  const sameScope=()=>loadId.current===generation&&live.current.project===s.project&&live.current.file?.path===path;
  const output=s.file.line_ending==='CRLF'?s.text.replace(/\n/g,'\r\n'):s.text;
  const matches=(f:Content|null|undefined):boolean=>!!f&&f.path===path&&typeof f.content==='string'&&f.content===output&&typeof f.etag==='string'&&/^[0-9a-f]{64}$/.test(f.etag)&&typeof f.line_ending==='string'&&f.bom===s.file!.bom&&typeof f.editable==='boolean';
  saveLock.current=true;setSaving(true);setError('');
  try{
   let f:Content,verified=false;
   try{
    const receipt=await api<Content>(url,{path,content:output,etag:s.file.etag},'PUT');
    if(!matches(receipt))throw Object.assign(new Error(translateUI('errors:LOCAL_RESPONSE_INVALID')),{code:'LOCAL_SERVICE_RESPONSE_INVALID'});
    f=receipt;
   }catch(error){
    const info=error as {code?:string;httpStatus?:number};
    const uncertain=['LOCAL_SERVICE_UNAVAILABLE','LOCAL_SERVICE_RESPONSE_INVALID','SERVICE_UNAVAILABLE'].includes(info?.code||'')||(info?.httpStatus||0)>=500;
    if(!uncertain||!sameScope())throw error;
    setRecoveryStatus(translateUI('navigation:saveReceiptChecking',{seconds:SAVE_RECEIPT_CHECK_MS/1000}));
    let observed:Content|null=null,readError:unknown=null,timedOut=false;
    const controller=new AbortController();
    const timer=window.setTimeout(()=>{timedOut=true;controller.abort();},SAVE_RECEIPT_CHECK_MS);
    try{observed=await api<Content>(url+'?path='+encodeURIComponent(path),undefined,'GET',{signal:controller.signal});}
    catch(e){readError=timedOut?new Error(translateUI('navigation:saveReceiptTimedOut',{seconds:SAVE_RECEIPT_CHECK_MS/1000})):e;}
    finally{window.clearTimeout(timer);}
    if(!observed||!matches(observed)){
     const different=!!observed&&typeof observed.etag==='string'&&observed.etag!==s.file.etag;
     if(different&&sameScope())setConflict(true);
     const reason=String(readError||error).replace(/^Error: /,'');
     throw Object.assign(new Error(translateUI(different?'navigation:saveReceiptDifferent':'navigation:saveReceiptUncertain')+' '+reason),{code:different?'SAVE_RECEIPT_DIFFERENT':'SAVE_RECEIPT_UNCERTAIN'});
    }
    f=observed;verified=true;
    // Invalidate existing statistics only. A read-back never creates a save event.
    if(isManuscriptPath(path))invalidateWritingMetrics(s.project,'save');
   }
   if(sameScope()){
    const recoveryText=live.current.text;
    setFile(f);if(recoveryText===s.text)setText(normalized(f));
    setConflict(false);setRecovery(null);setAutosaveFailed(false);
    const body=path.startsWith('chapters/story/')?s.text:splitText(s.text).body;
    const savedCounts={han:(body.match(/[\u3400-\u9fff]/g)||[]).length,characters:body.replace(/\s/g,'').length};
    setBoard(old=>old?{...old,chapters:old.chapters.map(c=>c.versions.some(v=>v.path===f.path)?{...c,han:savedCounts.han,characters:savedCounts.characters}:c)}:old);
    let retainedText:string|null=null,maintenanceError:string|null=null;
    try{
     if(recoveryText===s.text){
      const cached=readLocalRecovery(s.project,path);await cleanRecovery(s.project,path);
      // A completed cleanup is not permission to delete a newer local edit.
      if(sameScope()&&live.current.text===normalized(f))clearLocalRecovery(s.project,path,cached);
     }else{
      await writeRecovery(s.project,path,f.etag,recoveryText);retainedText=recoveryText;
     }
    }catch(e){maintenanceError=String(e).replace(/^Error: /,'');}
    if(sameScope()){
     const currentSaved=live.current.text===normalized(f);
     const maintenance=maintenanceError?translateUI(currentSaved?'navigation:manuscriptSavedRecoveryCleanupFailed':'navigation:manuscriptSavedRecoveryUpdateFailed')+' '+maintenanceError:null;
     setRecoveryStatus(maintenance||(!currentSaved?(retainedText===live.current.text?'恢复副本已保留':translateUI('navigation:newerInputUnsaved')):''));
     setNotice(maintenance||(currentSaved?translateUI(verified?'navigation:saveReceiptVerified':automatic?'navigation:manuscriptAutoSaved':'navigation:manuscriptSaved'):''));
    }
   }
   updatePrefs({last_edited_files:{...live.current.prefs.last_edited_files,[s.project]:path}});return true;
  }catch(e){if(sameScope()){
   const info=e as {code?:string;httpStatus?:number};
   // A rejected retry cannot establish the outcome of an earlier uncertain write.
   const different=info?.code==='SAVE_RECEIPT_DIFFERENT'||info?.httpStatus===409&&info?.code!=='WORKSPACE_BUSY'||s.saveNeedsVerification&&s.saveFailure==='conflict';
   const reason=different?'conflict':info?.code==='SAVE_RECEIPT_UNCERTAIN'||s.saveNeedsVerification?'unconfirmed':'failed';setAutosaveFailed(reason);if(reason==='conflict')setConflict(true);
   setRecoveryStatus(translateUI(reason==='conflict'?'navigation:saveReceiptDifferent':reason==='unconfirmed'?'navigation:saveReceiptUncertain':'navigation:manuscriptSaveFailed'));
   report(e);onFailure?.(String(e).replace(/^Error: /,''));
  }return false;}
  finally{saveLock.current=false;setSaving(false);}
 }


